import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import Icon from '@cetus/ui-kit/src/components/Icon'
import { Center, HStack, StackProps, Text, TextProps } from '@chakra-ui/react'
import AddressUnderLine from './AddressUnderline'
import { CetusTooltip, CopyButton } from './index'

interface AddressCopyLinkProps extends TextProps {
  address: string
  onClickLink: () => void
  onAddressClick?: () => void
  showCopy?: boolean
  showLink?: boolean
  addressWeight?: string
  addressColor?: string
  addressSize?: string
  hasUnderline?: boolean
  wrapStyle?: StackProps
  addressAbridgeStyle?: string
  showAddress?: boolean
  showCopyTooltip?: boolean
  showLinkTooltip?: boolean
  isAddressCancelBubble?: boolean
  subStringLengthStart?: number
  subStringLengthEnd?: number
}
export default function AddressCopyLink(props: AddressCopyLinkProps) {
  const {
    address,
    addressSize = '12px',
    showCopy = true,
    showLink = true,
    hasUnderline = true,
    addressWeight = '400',
    addressColor = 'text_paragraph',
    onClickLink,
    onAddressClick,
    wrapStyle = { gap: '4px' },
    addressAbridgeStyle,
    showAddress = true,
    showCopyTooltip = false,
    showLinkTooltip = false,
    subStringLengthStart = 6,
    subStringLengthEnd = 4,
    isAddressCancelBubble = true,
    ...rest
  } = props
  const { isApp } = useWindowWidth()
  return (
    <HStack align="center" {...wrapStyle}>
      {showAddress && (
        <AddressUnderLine
          address={address}
          addressAbridgeStyle={addressAbridgeStyle}
          hasUnderline={hasUnderline}
          isCancelBubble={isAddressCancelBubble}
          onClickLink={onAddressClick ? onAddressClick : onClickLink}
          subStringLengthStart={subStringLengthStart}
          subStringLengthEnd={subStringLengthEnd}
          {...rest}
        />
      )}
      {showCopy &&
        (showCopyTooltip ? (
          <CetusTooltip showTooltip={isApp ? false : true} placement="top" tooltip={<Text fontSize="12px">Copy address</Text>}>
            <Center>
              <CopyButton text={address} />
            </Center>
          </CetusTooltip>
        ) : (
          <CopyButton text={address} />
        ))}
      {showLink &&
        (showLinkTooltip ? (
          <CetusTooltip showTooltip={isApp ? false : true} placement="top" tooltip={<Text fontSize="12px">View on Explorer</Text>}>
            <Center>
              <Icon xlinkHref="#icon-icon_link1" onClick={onClickLink} />
            </Center>
          </CetusTooltip>
        ) : (
          <Icon xlinkHref="#icon-icon_link1" onClick={onClickLink} />
        ))}
    </HStack>
  )
}
