import { addressAbridge, cancelBubble } from '@cetus/utils'
import { Text, TextProps } from '@chakra-ui/react'

interface AddressUnderlineProps extends TextProps {
  address: string
  onClickLink: () => void
  hasUnderline?: boolean
  isCancelBubble?: boolean
  subStringLengthStart?: number
  subStringLengthEnd?: number
  addressAbridgeStyle?: string
}
export default function AddressUnderline(props: AddressUnderlineProps) {
  const {
    isCancelBubble = true,
    address,
    hasUnderline = true,
    onClickLink,
    addressAbridgeStyle,
    subStringLengthStart = 6,
    subStringLengthEnd = 4,
    ...rest
  } = props
  return (
    <Text
      cursor="pointer"
      color="text_paragraph"
      fontSize="12px"
      fontWeight="400"
      sx={{
        _hover: {
          textDecoration: hasUnderline ? 'underline' : 'none'
        }
      }}
      onClick={e => {
        if (isCancelBubble) {
          cancelBubble(e)
        }
        onClickLink()
      }}
      {...rest}
    >
      {addressAbridge(address, addressAbridgeStyle, subStringLengthStart, subStringLengthEnd)}
    </Text>
  )
}
